#!/usr/bin/env bash
# Usage: scripts/package-atem-client-apple.sh <version> <output-dir> [--conformance]
#
# AtemClient for Astation's Apple apps: libatem_client_ffi.a for macOS
# (arm64 + x86_64), iOS (arm64) and the iOS simulator (arm64 + x86_64) in
# AtemClientFFI.xcframework (with the UniFFI C header and module map), and a
# SwiftPM package around it (<output-dir>/AtemClient: Package.swift,
# Sources/AtemClient/atem_client_ffi.swift generated by uniffi-bindgen).
# Release: also the zipped package and SHA-256 sums. macOS only.
#
# --conformance: the host's macOS slice only, built with the test features
# (software-keys, test-vectors) and the Swift conformance tests
# (Tests/AtemClientTests) included; `swift test` in <output-dir>/AtemClient
# with ATEM_FIXTURES=designs/protocol/fixtures. Never shipped.
set -euo pipefail
VERSION="$1"
OUT="$2"
CONFORMANCE=0
[ "${3:-}" = "--conformance" ] && CONFORMANCE=1
cd "$(dirname "$0")/.."
ROOT=$(pwd)
TARGET=${CARGO_TARGET_DIR:-$ROOT/target}
mkdir -p "$OUT"
OUT="$(cd "$OUT" && pwd)"
FEATURES=()
[ $CONFORMANCE = 1 ] && FEATURES=(--features software-keys,test-vectors)
BINDGEN_FEATURES=bindgen
[ $CONFORMANCE = 1 ] && BINDGEN_FEATURES=bindgen,software-keys,test-vectors

# The Swift side, generated from a host build with the same exports.
cargo build -p atem-client-ffi --features "$BINDGEN_FEATURES"
WORK="$(mktemp -d)"
"$TARGET/debug/uniffi-bindgen" generate --no-format --library "$TARGET/debug/libatem_client_ffi.dylib" \
  --language swift --out-dir "$WORK/gen"
mkdir -p "$WORK/include"
cp "$WORK/gen/atem_client_ffiFFI.h" "$WORK/include/"
cp "$WORK/gen/atem_client_ffiFFI.modulemap" "$WORK/include/module.modulemap"

lib() { echo "$TARGET/$1/release/libatem_client_ffi.a"; }
build() { cargo build -p atem-client-ffi --release --target "$1" ${FEATURES[@]+"${FEATURES[@]}"}; }
if [ $CONFORMANCE = 1 ]; then
  case "$(uname -m)" in arm64) HOST=aarch64-apple-darwin ;; *) HOST=x86_64-apple-darwin ;; esac
  build "$HOST"
  XCF_ARGS=(-library "$(lib "$HOST")" -headers "$WORK/include")
else
  for t in aarch64-apple-darwin x86_64-apple-darwin aarch64-apple-ios aarch64-apple-ios-sim x86_64-apple-ios; do
    build "$t"
  done
  mkdir -p "$WORK/macos" "$WORK/ios-sim"
  lipo -create "$(lib aarch64-apple-darwin)" "$(lib x86_64-apple-darwin)" -output "$WORK/macos/libatem_client_ffi.a"
  lipo -create "$(lib aarch64-apple-ios-sim)" "$(lib x86_64-apple-ios)" -output "$WORK/ios-sim/libatem_client_ffi.a"
  XCF_ARGS=(-library "$WORK/macos/libatem_client_ffi.a" -headers "$WORK/include"
            -library "$(lib aarch64-apple-ios)" -headers "$WORK/include"
            -library "$WORK/ios-sim/libatem_client_ffi.a" -headers "$WORK/include")
fi

PKG="$OUT/AtemClient"
rm -rf "$PKG"
mkdir -p "$PKG/Sources/AtemClient"
xcodebuild -create-xcframework "${XCF_ARGS[@]}" -output "$PKG/AtemClientFFI.xcframework"
cp "$WORK/gen/atem_client_ffi.swift" "$PKG/Sources/AtemClient/"
SWIFT=crates/atem-client-ffi/bindings/swift
if [ $CONFORMANCE = 1 ]; then
  cp "$SWIFT/Package.swift" "$PKG/"
  mkdir -p "$PKG/Tests"
  cp -R "$SWIFT/Tests/AtemClientTests" "$PKG/Tests/"
  echo "Conformance package in $PKG (swift test, ATEM_FIXTURES=$ROOT/designs/protocol/fixtures)"
  exit 0
fi
grep -v '// conformance$' "$SWIFT/Package.swift" > "$PKG/Package.swift"

ZIP="atem-client-${VERSION}-apple-swiftpm.zip"
(cd "$OUT" && ditto -c -k --keepParent AtemClient "$ZIP")
cp "$WORK/gen/atem_client_ffiFFI.h" "$OUT/atem-client-${VERSION}-atem_client_ffiFFI.h"
(cd "$OUT" && shasum -a 256 "$ZIP" "atem-client-${VERSION}-atem_client_ffiFFI.h" > "atem-client-${VERSION}-SHA256SUMS.txt")
echo "Packaged into $OUT:"
ls -l "$OUT"
